request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-006

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "TRANSLATES_SCHEMA_EVIDENCE_INTO_PROCESSING_PROCEDURE",
    "definition": "An observation supplies structural, schema, field-list, format, or documented layout information about a resource; the reasoning uses that structural information to determine which fields, parameters, or operations the task requires; and an action creates or executes a procedure that implements that determination.",
    "parameters": [
      {
        "name": "schema_observation",
        "type": "observation",
        "description": "The observation containing schema, field, format, or documented layout information about the resource."
      },
      {
        "name": "interpretation_reasoning",
        "type": "reasoning",
        "description": "The reasoning that maps the task requirements onto the fields, parameters, or operations indicated by the structural evidence."
      },
      {
        "name": "implementation_action",
        "type": "action",
        "description": "The action creating or executing a procedure that implements the determined interpretation."
      }
    ],
    "assertion_conditions": [
      "The observation contains structural, schema, field-list, format, or documented layout information relevant to the resource.",
      "The reasoning explicitly uses that structural information to determine which fields, parameters, or operations the task requires.",
      "The action creates or executes a procedure that operationalizes the interpretation rather than merely retrieving or inspecting data."
    ],
    "exclusion_conditions": [
      "The observation contains only values or results without structural or schema information.",
      "The reasoning does not reference the structural or field information when determining the procedure.",
      "The action retrieves or inspects data but does not implement a procedure derived from the structural evidence."
    ]
  },
  {
    "name": "RETRIEVES_MISSING_SECTION_WITH_FOLLOWUP",
    "definition": "A follow-up action is deliberately scoped to obtain the portion of information missing from a prior partial or truncated observation, and the resulting observation supplies that previously missing portion.",
    "parameters": [
      {
        "name": "gap_reasoning",
        "type": "reasoning",
        "description": "The reasoning identifying the specific portion missing from a prior partial observation."
      },
      {
        "name": "followup_action",
        "type": "action",
        "description": "The action targeted at retrieving the missing section, range, or remainder of the information."
      },
      {
        "name": "followup_observation",
        "type": "observation",
        "description": "The result that supplies the previously missing information."
      }
    ],
    "assertion_conditions": [
      "The reasoning identifies a specific missing portion (section, line range, field, or remainder) of a prior partial or truncated observation.",
      "The follow-up action targets that missing portion, for example by requesting the next range or the remainder, rather than repeating the entire retrieval.",
      "The follow-up observation contains the information that was identified as missing."
    ],
    "exclusion_conditions": [
      "The follow-up action is unrelated to the identified missing portion.",
      "The follow-up action merely re-fetches the same information already available.",
      "The follow-up observation does not supply the missing content identified in the reasoning.",
      "No prior observation is recognized as partial, so there is no identified gap."
    ]
  }
]

