["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA", "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE", "CONDUCTS_CONCERN_MOTIVATED_EVIDENCE_GATHERING", "IMPLEMENTS_REASONED_FAILURE_OR_RISK_RESPONSE_WITH_OBSERVED_EVIDENCE", "RECOVERS_UNUSABLE_CHECK_RESULT_VIA_METHOD_DIAGNOSIS_AND_ALTERNATIVE_RETRIEVAL", "CONFIRMS_ABSENCE_OF_UNWANTED_STATE_OR_CONTENT"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "INTERPRETS_OBSERVED_STRUCTURE_OR_INFORMATIONAL_GAP_TO_DIRECT_TARGETED_ACTION",
  "definition": "Reasoning interprets observed informational content that is either structural, schema, field-list, format, or documented-layout evidence about a resource, or a recognized missing or truncated portion of prior information. The reasoning thereby determines a specific required operation: the fields, parameters, or procedure to implement, or the missing information portion to retrieve. A targeted action is directed by that reasoning to create or execute the corresponding procedure or to perform a follow-up retrieval specifically aimed at the identified missing portion. The linked observation is the informational content involved: it either supplies the structural or layout evidence used by the reasoning or contains the previously missing portion returned by the targeted action. The action must operationalize or complete the interpreted informational requirement rather than merely inspect unrelated data or repeat already available information.",
  "parameters": [
    {
      "name": "interpretive_reasoning",
      "type": "reasoning",
      "description": "The reasoning that interprets structural, schema, field-list, format, or layout evidence to determine required fields, parameters, or operations, or identifies a specific missing or truncated portion of prior information."
    },
    {
      "name": "targeted_action",
      "type": "action",
      "description": "The action directed by the reasoning to implement or execute the corresponding procedure or to perform a follow-up retrieval aimed at the identified missing portion."
    },
    {
      "name": "linked_observation",
      "type": "observation",
      "description": "The observation that either supplies the structural or layout evidence interpreted by the reasoning or contains the previously missing content obtained by the targeted action."
    }
  ],
  "assertion_conditions": [
    "The interpretive reasoning explicitly references structural, schema, field-list, format, or documented layout information, or identifies a specific missing or truncated portion of prior information.",
    "The targeted action is causally linked to that interpretation, either by implementing or executing a procedure based on the structural determination or by performing a follow-up retrieval aimed at the identified missing portion rather than unrelated or duplicative retrieval.",
    "The linked observation contains either the structural or layout evidence used by the reasoning or the missing content identified and returned by the targeted action.",
    "The action operationalizes the interpreted requirement or obtains the identified missing portion; it does not merely inspect data unrelated to the interpretation or repeat already available information."
  ],
  "exclusion_conditions": [
    "The interpretive reasoning relies only on values or results without structural, schema, field-list, format, or layout information and does not identify a specific missing or truncated portion.",
    "The targeted action is unrelated to the identified structure or missing portion, or merely re-fetches information already available.",
    "The linked observation contains neither structural or layout evidence used by the reasoning nor the missing content identified as missing.",
    "For the missing-portion case, no prior observation is recognized as partial or truncated.",
    "The action only retrieves or inspects data and neither implements a procedure derived from structural evidence nor retrieves the identified missing portion."
  ]
}

